// lib/utils/l10n_ext.dart
//
// Short access to the translated texts:
//   Text(context.l10n.navHome)
//   Text(context.l10n.drawerCart(5))
//
// AppLocalizations is generated by Flutter from lib/l10n/*.arb
// (run `flutter pub get` or `flutter gen-l10n` once after adding a key).

import 'package:flutter/widgets.dart';
import '../l10n/app_localizations.dart';

export '../l10n/app_localizations.dart';

extension L10nX on BuildContext {
  AppLocalizations get l10n => AppLocalizations.of(this);
}
